package com.queueless.controller;
import com.queueless.dao.QueueDAO; import com.queueless.model.QueueEntry; import com.queueless.util.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*;
@WebServlet("/api/queue/status") public class QueueStatusServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{res.setContentType("application/json;charset=UTF-8");try{String token=req.getParameter("token");if(token==null||token.isBlank())throw new IllegalArgumentException("Token is required.");QueueDAO d=new QueueDAO();QueueEntry q=d.findByToken(token.trim().toUpperCase());if(q==null){res.setStatus(404);res.getWriter().write(JsonUtil.error("Token not found."));return;}int ahead=("WAITING".equals(q.status))?d.peopleAhead(q):0;QueueEntry current=d.current(q.serviceId);int avg=5;try{var s=new com.queueless.dao.ServiceDAO().find(q.serviceId);if(s!=null)avg=s.averageTime;}catch(Exception ignored){}int wait=ahead*avg;String serving=current==null?"—":current.token;res.getWriter().write("{\"success\":true,\"token\":\""+q.token+"\",\"name\":\""+JsonUtil.esc(q.name)+"\",\"service\":\""+JsonUtil.esc(q.serviceName)+"\",\"status\":\""+q.status+"\",\"currentlyServing\":\""+serving+"\",\"peopleAhead\":"+ahead+",\"estimatedWait\":"+wait+",\"registrationType\":\""+q.registrationType+"\"}");}catch(IllegalArgumentException e){res.setStatus(400);res.getWriter().write(JsonUtil.error(e.getMessage()));}catch(Exception e){res.setStatus(500);res.getWriter().write(JsonUtil.error("Unable to load queue status."));}}
}
